sharedContracts.interfaceSketch:
interface ProvenanceTarget { readonly file: string; readonly version?: string; readonly segment?: { readonly startLine: number; readonly endLine: number }; }
interface ProvenanceAuthorship { readonly author: string; readonly timestamp: string; }
interface FeedbackEntry extends ProvenanceAuthorship { readonly id: string; readonly target: ProvenanceTarget; readonly comment: string; readonly kind?: 'feedback' | 'suggestion' | 'comment'; }
interface ChangeLogEntry extends ProvenanceAuthorship { readonly target: ProvenanceTarget; readonly summary?: string; }
type FeedbackRecord = readonly FeedbackEntry[];
type ChangeLog = readonly ChangeLogEntry[];
// additive optional body fields:
interface WithFeedback { readonly feedback?: FeedbackRecord; }   // DefineBody/HldBody/LldBody/PlanBody + BUILD body
interface WithChangeLog { readonly changeLog?: ChangeLog; }      // BUILD body only

interface AppendFeedbackRequest { readonly artifactPath: string; readonly entry: Omit<FeedbackEntry, 'id' | 'timestamp'> & { readonly timestamp?: string }; }
interface AppendFeedbackResult { readonly artifactPath: string; readonly entryId: string; readonly total: number; }
// production writer (new): (path: string, artifact: ArtifactShape) => void  // key-preserving rewrite
// daemon tool wrapper: registerArtifactFeedbackTool(): void
// IPC method name: 'artifact.feedback.append' => AppendFeedbackResult

// pure, structural render-binding declarations (no bodies)
type FeedbackSectionBinding = (feedback: FeedbackRecord | undefined) => readonly string[];
type ChangeLogSectionBinding = (changeLog: ChangeLog | undefined) => readonly string[];
interface ProvenanceBindings { readonly feedbackBodyLines: FeedbackSectionBinding; readonly changeLogBodyLines: ChangeLogSectionBinding; }
